NEW_FILES = {'open_floor_rules.py': '#!/usr/bin/env python3\n"""\nopen_floor_rules.py  --  two rooms that meet with no wall between them: one floor, or two rooms\n=============================================================================================\nDeli Counter 0.234.0 (the factory\'s roadmap 260). layout_lint L26 (0.223.0) names every pair of rooms on one storey\nwhose shared edge no partition covers for `tactical.OPEN_FLOOR_M` and that no room\'s `open_to` names. The library had\n49 such pairs in 26 specs (`open_floor_baseline.json`), frozen for the walker to sort one pair at a time. They are 20\npairs of room ids repeated through shared recipes, so they are sorted here once, by pair: a row says the floor is meant\n(OPEN) or the two rooms are two rooms (WALL), and one row moves every building that has the pair.\n\nTHE WALKER\'S CALLS, 2026-10-19 (the factory\'s docs/findings/walker_review_2026-10-19/). The rows below are the\ndefaults offered and approved in chat -- "go ahead with the 255 table, your defaults are good" -- after the review\npage had answered "Wall it" for every pair while the walker was unsure whether a wall would shut a room nobody could\nopen: "we aren\'t making the doors in level factory because we are going to have networked doors added later". A wall\nhere shuts no room by itself: a door opening in it ships as a door socket like every other (Dispatch\'s\n`interactives.json`), and layout_lint L12 fails a room nothing reaches. Three rows depart from what was offered,\neach because a stair stands on the line, the factory\'s call until the walker asks otherwise: the office\'s lobby and\nbullpen meet along y 0, where `office_stair_0` stands, and corner_deli_heist_01\'s stair well meets its two cold rooms\nalong edges the stair itself reaches or a door sits on (the rows say where). They are OPEN.\n\nThe gas stations\' three forecourt rows never fire on today\'s library: those rooms meet along the footprint\'s own\nedge, where the exterior wall stands, and since 0.234.0 the open-floor reading counts it (`tactical.exterior_parts`).\nThe rows stay as the walker\'s sort for a forecourt that meets a shop inside the footprint.\n\nWHAT A ROW DOES (`apply`):\n  OPEN  the second room\'s id goes into the first\'s `open_to`, the schema\'s word for "this floor is meant".\n  WALL  each stretch of the meeting line no partition covers is closed. A partition on that line whose run ends at\n        the stretch is extended over it, each of its openings kept where the builder stood it (`snap(pos * run)` from\n        the run\'s middle); otherwise a partition is added for the stretch alone, in the material of the storey\'s\n        partitions. An opening on a crossing wall that a new wall\'s end would split (layout_lint L18) slides along\n        its own wall, whole grid cells away, until the end clears it -- L18\'s own prescription -- or the pair is\n        refused. Then, under DOORWAY_POLICY, one door, as wide as the agent contract\'s, in the longest stretch\n        closed: "keep_pair_joined" (the default) when nothing walkable joins the two rooms any more, so no way the\n        open floor gave is lost; "only_if_sealed" only when L12 or L24 would otherwise newly name one of them. Never\n        into an objective room (the walker, 2026-10-06: a room reachable only by breaching gets a door unless it is\n        the objective). A WALL row that would leave the spec failing any lint rule it passed is taken back whole,\n        and the pair is named as refused.\nA pair with no row is left alone, and L26 keeps naming it. A spec already sorted is left alone: `apply` twice is\n`apply` once. A partition is extended only when every opening it carries is built where it was: the grid places an\nopening at `snap(pos * run)` from the run\'s middle, so a longer run can slide a door by half a cell (measured on\ncorner_deli_heist_01\'s `cold_w_access`, 0.125 m), and the stretch then gets a partition of its own.\n"""\nimport copy\n\nimport layout_lint\n\nOPEN = "open"\nWALL = "wall"\n\n#: One row per pair of room ids, the order inside a pair immaterial. The walker\'s calls of 2026-10-19 (above).\nRULES = {\n    # the delis: the service counter divides the floor from the counter, not a wall; the kitchen is its own room\n    ("customer_floor", "deli_counter"): OPEN,\n    ("market_aisles", "kitchen"): WALL,\n    # corner_deli_heist_01\'s walk-in cold rooms; the stair well between two of them opens onto both, the factory\'s\n    # call where the walker\'s was WALL: `main_stack` reserves y 6.05..12.65, so a wall on the well\'s south edge\n    # (y 6.25) runs inside the stair and the builder deletes it (L21), and the north edge (y 12.95) ends on the\n    # x -13.2 wall at the centre of `cold_n_access` (L18) -- both edges are the stair\'s own way on and off\n    ("cold_storage_w", "cold_storage_s"): WALL,\n    ("main_stack_well_b", "cold_storage_n"): OPEN,\n    ("main_stack_well_b", "cold_storage_s"): OPEN,\n    # the gas stations (see the docstring: the exterior wall already stands there)\n    ("forecourt", "sales_floor"): WALL,\n    ("forecourt", "stockroom"): WALL,\n    ("forecourt", "restroom"): WALL,\n    # the upper floors of the auto shops and the pawn shops\n    ("upper_office", "upper_storage"): WALL,\n    ("apartment", "upper_storage"): WALL,\n    # the rowhouse and the walk-up\n    ("front_hall", "kitchen"): OPEN,\n    ("front_hall", "garage_bay"): WALL,\n    ("kitchen", "garage_bay"): WALL,\n    ("office", "bedroom"): WALL,\n    ("basement_vault", "basement_approach"): WALL,\n    # a parking deck is one deck\n    ("deck_0_south", "deck_0_main"): OPEN,\n    ("deck_1", "deck_1_west"): OPEN,\n    # the office: the anteroom opens off its lobby; the ground floor\'s stair stands on the lobby\'s edge\n    ("exec_lobby", "exec_anteroom"): OPEN,\n    ("lobby", "ground_bullpen"): OPEN,\n    # the warehouse: the aisles run onto the dock\n    ("north_aisles", "north_dock"): OPEN,\n}\n\n#: Where a WALL row puts a door. "keep_pair_joined": whenever nothing walkable joins the two rooms once the line is\n#: closed. "only_if_sealed": only when layout_lint L12 or L24 would otherwise newly name one of them. A call made\n#: 2026-10-19 and meant to be changed.\nDOORWAY_POLICY = "keep_pair_joined"\nPOLICIES = ("keep_pair_joined", "only_if_sealed")\n\n#: A partition counts as on the meeting line, or as ending at a stretch, within this: `tactical.open_edge`\'s own\n#: tolerance for a partition on the line.\nLINE_TOL = 0.05\n\n\ndef rule(a, b):\n    """The row for rooms `a` and `b` in either order, or None."""\n    return RULES.get((a, b)) or RULES.get((b, a))\n\n\ndef _snap(v, grid):\n    return round(v / grid) * grid\n\n\ndef _grid(spec):\n    """The spec\'s grid, or `LevelSpec`\'s default when the dict leaves it out: the builder snaps to that one."""\n    return float(layout_lint._spec_value(spec, "grid"))\n\n\ndef _ends(spec, p):\n    """``(start, end)`` of a partition\'s run as the builder reads it: the footprint on its axis when unset."""\n    hx, hy = float(spec["footprint_x"]) / 2.0, float(spec["footprint_y"]) / 2.0\n    lo, hi = (-hx, hx) if p["axis"] == "X" else (-hy, hy)\n    s = lo if p.get("start") is None else float(p["start"])\n    e = hi if p.get("end") is None else float(p["end"])\n    return s, e\n\n\ndef _built_at(spec, p, o):\n    """Where the builder stands opening `o` of partition `p` on its line: ``snap(pos * run)`` from the run\'s middle."""\n    s, e = _ends(spec, p)\n    return (s + e) / 2.0 + _snap(float(o.get("pos", 0.0)) * (e - s), _grid(spec))\n\n\ndef _stretches(spec, story, axis, line, lo, hi):\n    """The stretches of [lo, hi] on the line that no same-axis partition on it covers, longest first."""\n    cover = []\n    for p in spec.get("partitions") or []:\n        if int(p.get("story", 0) or 0) != story or p.get("axis") != axis or abs(float(p["pos"]) - line) >= LINE_TOL:\n            continue\n        s, e = sorted(_ends(spec, p))\n        if min(e, hi) > max(s, lo):\n            cover.append((max(s, lo), min(e, hi)))\n    out, at = [], lo\n    for s, e in sorted(cover):\n        if s - at >= LINE_TOL:\n            out.append((at, s))\n        at = max(at, e)\n    if hi - at >= LINE_TOL:\n        out.append((at, hi))\n    return sorted(out, key=lambda g: g[0] - g[1])\n\n\ndef _extend(spec, p, g0, g1):\n    """Extend partition `p`\'s run over [g0, g1], keeping each opening where it is built. ``[what moved]``: an\n    opening the grid cannot put back exactly where it stood, named with how far."""\n    built = [_built_at(spec, p, o) for o in p.get("openings") or ()]\n    s, e = _ends(spec, p)\n    if abs(max(s, e) - g0) < LINE_TOL:\n        if e >= s:\n            e = g1\n        else:\n            s = g1\n    else:\n        if e >= s:\n            s = g0\n        else:\n            e = g0\n    p["start"], p["end"] = s, e\n    moved = []\n    for o, at in zip(p.get("openings") or (), built):\n        o["pos"] = (at - (s + e) / 2.0) / (e - s)\n        now = _built_at(spec, p, o)\n        if abs(now - at) > 1e-6:\n            moved.append("%s %s moved %+.3f m by the grid" % (o.get("kind"), o.get("tag", ""), now - at))\n    return moved\n\n\ndef _material(spec, story, axis, line):\n    """The material for a new partition: a partition\'s on the same line, else the storey\'s commonest, else drywall."""\n    same, story_mats = [], {}\n    for p in spec.get("partitions") or []:\n        if int(p.get("story", 0) or 0) != story or not p.get("material"):\n            continue\n        story_mats[p["material"]] = story_mats.get(p["material"], 0) + 1\n        if p.get("axis") == axis and abs(float(p["pos"]) - line) < LINE_TOL:\n            same.append(p["material"])\n    if same:\n        return same[0]\n    if story_mats:\n        return sorted(story_mats.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]\n    return "drywall"\n\n\ndef _walk_joined(spec, a, b):\n    """Is there a walkable opening (layout_lint.WALK_KINDS) straight between rooms `a` and `b`?"""\n    edges, _ = layout_lint.graph(spec)\n    return any(n == b and k in layout_lint.WALK_KINDS for n, k in edges.get(a, ()))\n\n\ndef _named(spec):\n    """The room ids layout_lint L12 or L24 names in `spec`."""\n    out = set()\n    reach = layout_lint._reach_from_ext(spec)\n    walk = layout_lint._reach_from_ext(spec, walk_only=True)\n    for r in spec.get("rooms") or []:\n        if r["id"] not in reach or r["id"] not in walk:\n            out.add(r["id"])\n    return out\n\n\ndef _objective(spec, room_id):\n    for r in spec.get("rooms") or []:\n        if r["id"] == room_id:\n            return bool(r.get("objective")) or r.get("role") == "objective_room"\n    return False\n\n\ndef _door(spec, p, g0, g1, a, b):\n    """Put one door, the agent contract\'s width, in the middle of [g0, g1] on partition `p`, or say why not."""\n    import agent_contract\n    width = agent_contract.min_door_width()\n    s, e = _ends(spec, p)\n    mid = (s + e) / 2.0\n    at = mid + _snap((g0 + g1) / 2.0 - mid, _grid(spec))\n    if at - width / 2.0 < g0 - 1e-6 or at + width / 2.0 > g1 + 1e-6:\n        return None, "no door: %.2f m of new wall cannot hold a %.2f m door clear of its ends" % (g1 - g0, width)\n    p.setdefault("openings", []).append({"kind": "door", "pos": (at - mid) / (e - s), "width": width,\n                                         "tag": "%s_to_%s" % (a, b)})\n    return at, None\n\n\ndef _centre(spec, p, o):\n    """Where layout_lint\'s L18 reads opening `o` of partition `p`: ``pos * run`` from the run\'s middle, unsnapped\n    (`partition_bounds.host_openings`\' convention)."""\n    s, e = _ends(spec, p)\n    return (s + e) / 2.0 + float(o.get("pos", 0.0)) * (e - s)\n\n\ndef _sides(spec, p, at):\n    """The rooms either side of partition `p` at `at` along it, as layout_lint\'s graph reads a doorway."""\n    rooms = layout_lint._rooms_by_story(spec).get(int(p.get("story", 0) or 0), [])\n    line = float(p["pos"])\n    if p["axis"] == "X":\n        pts = ((at, line - 0.6), (at, line + 0.6))\n    else:\n        pts = ((line - 0.6, at), (line + 0.6, at))\n    got = [layout_lint._room_at(rooms, x, y) for x, y in pts]\n    return tuple(r["id"] if r else None for r in got)\n\n\ndef _clear_apertures(spec, term):\n    """Slide each opening a new wall\'s end would split (layout_lint L18) along its own wall, whole grid cells away\n    from the end, until the end clears it: L18\'s own prescription, "nudge the opening along its wall". It stays on its\n    wall\'s run, clear of the wall\'s other openings and of every other wall ending on it, and between the same two\n    rooms, or it does not move. ``[what slid]`` and ``[what could not]``."""\n    import partition_bounds\n    grid = _grid(spec)\n    margin = layout_lint.LEAF_MARGIN\n    meet = float(layout_lint._spec_value(spec, "wall_thick")) + 0.05\n    fx, fy = float(spec["footprint_x"]), float(spec["footprint_y"])\n    t_ax, t_pos = term["axis"], float(term["pos"])\n    t_story = int(term.get("story", 0) or 0)\n    lo, hi = partition_bounds.clamp_partition_span(*_ends(spec, term), t_ax, fx, fy)\n    moved, stuck = [], []\n    parts = spec.get("partitions") or []\n    for end in (lo, hi):\n        for host in parts:\n            if host is term or host.get("axis") == t_ax or int(host.get("story", 0) or 0) != t_story:\n                continue\n            if abs(end - float(host["pos"])) > meet:\n                continue\n            h_lo, h_hi = sorted(_ends(spec, host))\n            others = [q for q in parts if q is not host and q.get("axis") != host.get("axis")\n                      and int(q.get("story", 0) or 0) == t_story\n                      and any(abs(v - float(host["pos"])) <= meet\n                              for v in partition_bounds.clamp_partition_span(*_ends(spec, q), q["axis"], fx, fy))]\n            for o in host.get("openings") or []:\n                w = float(o.get("width", 1.0))\n                need = w / 2.0 + margin\n                c = _centre(spec, host, o)\n                if abs(t_pos - c) >= need:\n                    continue\n                s, e = _ends(spec, host)\n                mid, run = (s + e) / 2.0, e - s\n                built = _built_at(spec, host, o)\n                rooms = _sides(spec, host, built)\n                away = 1.0 if c > t_pos or (c == t_pos and mid > t_pos) else -1.0\n                done = False\n                for k in range(1, 7):                  # at most 3 m, on the builder\'s grid\n                    at = built + away * k * grid\n                    if abs(t_pos - at) < need:\n                        continue\n                    if at - w / 2.0 < h_lo + margin or at + w / 2.0 > h_hi - margin:\n                        break                          # off its wall\'s run\n                    if any(abs(at - _centre(spec, host, o2)) < (w + float(o2.get("width", 1.0))) / 2.0 + margin\n                           for o2 in host.get("openings") or [] if o2 is not o):\n                        continue                       # onto another opening\n                    if any(abs(float(q["pos"]) - at) < need for q in others):\n                        continue                       # onto another wall\'s end\n                    if _sides(spec, host, at) != rooms:\n                        break                          # between other rooms\n                    o["pos"] = (at - mid) / run\n                    moved.append("%s %s slid %+.2f m along its wall to clear the new wall\'s end (L18)"\n                                 % (o.get("kind", "door"), o.get("tag", ""), at - built))\n                    done = True\n                    break\n                if not done:\n                    stuck.append("%s %s" % (o.get("kind", "door"), o.get("tag", "")))\n    return moved, stuck\n\n\ndef _fail_codes(spec):\n    """How many of each layout_lint FAIL `spec` carries, by rule: ``{"L18": 1, ...}``."""\n    _name, fails, _warns = layout_lint.lint_spec(spec, spec.get("name", "?"))\n    out = {}\n    for f in fails:\n        code = f.split(" ", 1)[0]\n        out[code] = out.get(code, 0) + 1\n    return out\n\n\ndef apply(spec, policy=None):\n    """Sort `spec`\'s open floors by `RULES`, in place. ``[what changed]``, empty when nothing did.\n\n    A WALL row is applied to one pair at a time, and taken back whole when it would leave the spec failing a lint\n    rule it passed -- a wall through a stair\'s reservation (L21), say, or a doorway it could not clear (L18) -- so the\n    table never writes a wall the builder or the lint refuses; the pair is named as refused and L26 keeps naming it."""\n    policy = policy or DOORWAY_POLICY\n    if policy not in POLICIES:\n        raise ValueError("doorway policy %r, not one of %s" % (policy, ", ".join(POLICIES)))\n    said = []\n    named_before = _named(spec) if policy == "only_if_sealed" else set()\n    for f in layout_lint.open_floors(spec):\n        a, b, st = f["a"], f["b"], f["story"]\n        row = rule(a, b)\n        if row is None:\n            continue\n        if row == OPEN:\n            room = [r for r in spec["rooms"] if r["id"] == a and int(r.get("story", 0) or 0) == st][0]\n            if b not in (room.get("open_to") or []):\n                room["open_to"] = sorted(set(room.get("open_to") or []) | {b})\n                said.append("%s|%s (story %d) open: %s.open_to += %s" % (a, b, st, a, b))\n            continue\n        if not _stretches(spec, st, f["axis"], f["pos"], f["lo"], f["hi"]):\n            continue\n        before, fails_before = copy.deepcopy(spec), _fail_codes(spec)\n        lines = _close(spec, f, a, b, st, policy, named_before)\n        fails_after = _fail_codes(spec)\n        worse = sorted(k for k, n in fails_after.items() if n > fails_before.get(k, 0))\n        if worse:\n            spec.clear()\n            spec.update(before)\n            said.append("%s|%s (story %d): REFUSED -- closing it would fail %s; left open, and L26 names it"\n                        % (a, b, st, ", ".join(worse)))\n            continue\n        said.extend(lines)\n    return said\n\n\ndef _close(spec, f, a, b, st, policy, named_before):\n    """Close one WALL pair\'s stretches, slide clear what the new walls would split, then the door. ``[what changed]``."""\n    said = []\n    axis, line = f["axis"], f["pos"]\n    closed = []\n    for g0, g1 in _stretches(spec, st, axis, line, f["lo"], f["hi"]):\n        on_line = [p for p in spec.get("partitions") or []\n                   if int(p.get("story", 0) or 0) == st and p.get("axis") == axis\n                   and abs(float(p["pos"]) - line) < LINE_TOL]\n        ends_here = [p for p in on_line\n                     if abs(max(_ends(spec, p)) - g0) < LINE_TOL or abs(min(_ends(spec, p)) - g1) < LINE_TOL]\n        moved = []\n        if ends_here:\n            # extended only when every opening it carries stays where it is built; else a piece of its own\n            moved = _extend(spec, copy.deepcopy(ends_here[0]), g0, g1)\n        if ends_here and not moved:\n            p = ends_here[0]\n            _extend(spec, p, g0, g1)\n            said.append("%s|%s (story %d) wall: the %s-partition at %s %g extended over %g..%g"\n                        % (a, b, st, axis, "y" if axis == "X" else "x", line, g0, g1))\n        else:\n            p = {"story": st, "axis": axis, "pos": line, "start": g0, "end": g1,\n                 "material": ends_here[0].get("material") if ends_here and ends_here[0].get("material")\n                 else _material(spec, st, axis, line), "openings": []}\n            spec.setdefault("partitions", []).append(p)\n            said.append("%s|%s (story %d) wall: a %s-partition added at %s %g, %g..%g%s"\n                        % (a, b, st, axis, "y" if axis == "X" else "x", line, g0, g1,\n                           (" -- extending the one beside it would have moved its " + "; ".join(moved))\n                           if moved else ""))\n        closed.append((g1 - g0, g0, g1, p))\n    for _n, _g0, _g1, p in closed:\n        slid, _stuck = _clear_apertures(spec, p)\n        said.extend("%s|%s: %s" % (a, b, x) for x in slid)\n    if not closed:\n        return said\n    if _objective(spec, a) or _objective(spec, b):\n        if not _walk_joined(spec, a, b):\n            said.append("%s|%s: no door -- %s is the objective, kept behind what it had"\n                        % (a, b, a if _objective(spec, a) else b))\n        return said\n    if policy == "keep_pair_joined":\n        want = not _walk_joined(spec, a, b)\n    else:\n        want = bool(({a, b} & _named(spec)) - named_before)\n    if not want:\n        return said\n    _, g0, g1, p = max(closed, key=lambda c: (c[0], -c[1]))\n    at, why = _door(spec, p, g0, g1, a, b)\n    said.append("%s|%s: %s" % (a, b, why if why else "a door at %s %+.2f, tagged %s_to_%s"\n                               % ("x" if axis == "X" else "y", at, a, b)))\n    return said\n', 'migrate_open_floor_rules.py': '#!/usr/bin/env python3\n"""\nmigrate_open_floor_rules.py  --  sort the library\'s open floors by the walker\'s table\n====================================================================================\nDeli Counter 0.234.0 (the factory\'s roadmap 260): the one-shot, idempotent migration over specs/*.json that applies\n`open_floor_rules.RULES` -- each pair of rooms meeting with no wall between them named one floor (`open_to`) or walled,\nwith a door where nothing walkable would join the two any more (`open_floor_rules.DOORWAY_POLICY`). `presets.make`\napplies the same table to every building it makes, so a regenerated spec comes out as this leaves the library.\n\nMEASURED FIRST (the factory\'s docs/findings/open_floor_table_260/pairs.py): 49 open floors in 26 specs, 20 pairs of\nroom ids. Seven met along a footprint\'s own edge, where the exterior wall stands -- the gas stations\' forecourts --\nand 0.234.0\'s reading of exterior walls (`tactical.exterior_parts`) leaves 42 here.\n\nThe mission\'s own `lf_*` shells are not touched: they are built every run, from the generator, not the library.\nChange the table and run this again: a pair already sorted the old way is not unsorted by it -- an OPEN row turned\nWALL finds no open floor to close while `open_to` names it; take that out of the spec first.\n\n    python migrate_open_floor_rules.py            # write specs/\n    python migrate_open_floor_rules.py --check    # report only; exit 1 if any spec would change\n    python migrate_open_floor_rules.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nimport open_floor_rules\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    folder = argv[argv.index("--dir") + 1] if "--dir" in argv else os.path.join(HERE, "specs")\n    changed = 0\n    for path in sorted(glob.glob(os.path.join(folder, "*.json"))):\n        if os.path.basename(path).startswith("lf_"):\n            continue\n        with io.open(path, encoding="utf-8") as fh:\n            d = json.load(fh)\n        if not d.get("rooms"):\n            continue\n        said = open_floor_rules.apply(d)\n        if not said:\n            continue\n        changed += 1\n        for line in said:\n            print("%s: %s" % (os.path.basename(path), line))\n        if not check:\n            io.open(path, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("%d spec(s) %s" % (changed, "to migrate" if check else "migrated"))\n    return 1 if (check and changed) else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'test_open_floor_rules.py': '"""The walker\'s table sorts open floors by room pair (open_floor_rules, 0.234.0; the factory\'s roadmap 260).\n\nTwo rooms meeting with no wall between them are one floor (`open_to`) or two rooms (a wall, with a door where\nnothing walkable would join them any more), by a row per pair of room ids, applied to the library by\n`migrate_open_floor_rules.py` and to every building `presets.make` makes. Beside it: an exterior wall covers its line\nas a partition does (`tactical.exterior_parts`), and a room may carry `open_to` into the typed spec.\n\nFAIL ON 0.233.0: there is no open_floor_rules; `spec_loader` refuses a room naming `open_to`; a room meeting an\noutdoor room along the exterior wall is an open floor; and `presets.make("corner_deli")` comes out with two.\n"""\nimport copy\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport agent_contract                # noqa: E402\nimport layout_lint                   # noqa: E402\nimport open_floor_rules              # noqa: E402\nimport presets                       # noqa: E402\nimport spec_loader                   # noqa: E402\nimport tactical                      # noqa: E402\n\nFRONT, BACK = [-5.0, -5.0, 0.0, 5.0], [0.0, -5.0, 5.0, 5.0]\n\n\ndef _spec(partitions=(), front=None, back=None):\n    """Two 5 x 10 m rooms side by side on story 0 meeting along x = 0, a door in from the west and one from the east."""\n    rooms = [dict({"id": "front", "story": 0, "bounds": list(FRONT)}, **(front or {})),\n             dict({"id": "back", "story": 0, "bounds": list(BACK)}, **(back or {}))]\n    return {"name": "t", "footprint_x": 10.0, "footprint_y": 10.0, "rooms": rooms,\n            "partitions": [copy.deepcopy(p) for p in partitions],\n            "ext_walls": [{"wall": "W", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]},\n                          {"wall": "E", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]}]}\n\n\ndef _line(spec):\n    return [p for p in spec["partitions"] if p["axis"] == "Y" and abs(p["pos"]) < 1e-9]\n\n\n@pytest.fixture\ndef table(monkeypatch):\n    def use(row):\n        monkeypatch.setattr(open_floor_rules, "RULES", {("front", "back"): row})\n    return use\n\n\ndef test_an_open_row_names_the_floor_and_moves_nothing(table):\n    table(open_floor_rules.OPEN)\n    s = _spec()\n    assert len(layout_lint.open_floors(s)) == 1\n    said = open_floor_rules.apply(s)\n    assert len(said) == 1 and "open" in said[0]\n    assert s["rooms"][0]["open_to"] == ["back"] and s["partitions"] == []\n    assert layout_lint.open_floors(s) == []\n    assert open_floor_rules.apply(s) == []                    # once is enough\n\n\ndef test_a_wall_row_extends_the_short_partition_and_keeps_its_door_where_it_stood(table):\n    table(open_floor_rules.WALL)\n    part = {"story": 0, "axis": "Y", "pos": 0.0, "start": -5.0, "end": 2.0,\n            "openings": [{"kind": "door", "pos": 0.0, "width": 1.25, "tag": "between"}]}   # built at y -1.5\n    s = _spec([part])\n    before = open_floor_rules._built_at(s, s["partitions"][0], s["partitions"][0]["openings"][0])\n    said = open_floor_rules.apply(s)\n    assert any("extended over 2..5" in x for x in said), said\n    (p,) = _line(s)\n    assert (p["start"], p["end"]) == (-5.0, 5.0)\n    assert abs(open_floor_rules._built_at(s, p, p["openings"][0]) - before) < 1e-9 and before == -1.5\n    assert len(p["openings"]) == 1                            # a door already joined them: none added\n    assert layout_lint.open_floors(s) == []\n\n\ndef test_a_wall_row_with_no_partition_adds_one_and_a_door_of_the_contracts_width(table):\n    table(open_floor_rules.WALL)\n    s = _spec()\n    open_floor_rules.apply(s)\n    (p,) = _line(s)\n    assert (p["start"], p["end"]) == (-5.0, 5.0) and p["material"] == "drywall"\n    (door,) = p["openings"]\n    assert door["kind"] == "door" and door["tag"] == "front_to_back"\n    assert door["width"] == agent_contract.min_door_width() == 1.25\n    edges, _ = layout_lint.graph(s)\n    assert ("back", "door") in edges["front"]\n    assert layout_lint.open_floors(s) == [] and layout_lint.reachability_findings(s) == []\n    assert open_floor_rules.apply(s) == []\n\n\ndef test_no_door_into_an_objective_room(table):\n    table(open_floor_rules.WALL)\n    s = _spec(back={"objective": True, "role": "objective_room"})\n    said = open_floor_rules.apply(s)\n    (p,) = _line(s)\n    assert p["openings"] == [] and any("is the objective" in x for x in said), said\n\n\ndef test_the_other_policy_puts_a_door_only_where_a_room_would_be_cut_off(table):\n    table(open_floor_rules.WALL)\n    s = _spec()\n    open_floor_rules.apply(s, policy="only_if_sealed")       # both rooms keep their own door outside\n    assert _line(s)[0]["openings"] == []\n    t = _spec()\n    t["ext_walls"] = t["ext_walls"][:1]                       # the back room\'s only way in was the open floor\n    open_floor_rules.apply(t, policy="only_if_sealed")\n    assert [o["tag"] for o in _line(t)[0]["openings"]] == ["front_to_back"]\n    with pytest.raises(ValueError):\n        open_floor_rules.apply(_spec(), policy="always")\n\n\ndef test_a_partition_whose_door_the_grid_would_slide_is_left_alone(table):\n    table(open_floor_rules.WALL)\n    # a run of 5.5 m, its door built at y -1.75 (snap(0.1 * 5.5) = 0.5 from the middle, -2.25); over 10 m the same\n    # place is -1.75 from the middle, which the 0.5 m grid rounds to -2.0: the door would slide 0.25 m\n    part = {"story": 0, "axis": "Y", "pos": 0.0, "start": -5.0, "end": 0.5,\n            "openings": [{"kind": "door", "pos": 0.1, "width": 1.25, "tag": "kept"}]}\n    s = _spec([part])\n    said = open_floor_rules.apply(s)\n    assert any("would have moved" in x for x in said), said\n    first, piece = _line(s)\n    assert (first["start"], first["end"]) == (-5.0, 0.5) and first["openings"][0]["pos"] == 0.1\n    assert (piece["start"], piece["end"]) == (0.5, 5.0)\n    assert layout_lint.open_floors(s) == []\n\n\ndef test_a_pair_with_no_row_is_left_for_l26():\n    s = _spec()\n    assert open_floor_rules.rule("front", "back") is None\n    assert open_floor_rules.apply(s) == [] and len(layout_lint.open_floors(s)) == 1\n\n\ndef test_the_table_reads_either_way_round_and_says_only_open_or_wall():\n    assert open_floor_rules.rule("deli_counter", "customer_floor") == open_floor_rules.OPEN\n    assert open_floor_rules.rule("kitchen", "market_aisles") == open_floor_rules.WALL\n    assert set(open_floor_rules.RULES.values()) <= {open_floor_rules.OPEN, open_floor_rules.WALL}\n    assert open_floor_rules.DOORWAY_POLICY in open_floor_rules.POLICIES\n\n\ndef test_an_exterior_wall_covers_its_line():\n    # a shop meeting its outdoor forecourt along the footprint\'s south edge, where the front wall stands\n    s = {"name": "t", "footprint_x": 10.0, "footprint_y": 10.0,\n         "rooms": [{"id": "forecourt", "story": 0, "bounds": [-5.0, -9.0, 5.0, -5.0]},\n                   {"id": "shop", "story": 0, "bounds": [-5.0, -5.0, 5.0, 5.0]}],\n         "partitions": [],\n         "ext_walls": [{"wall": "S", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]}]}\n    assert layout_lint.open_floors(s) == []\n    assert ("X", -5.0, -5.0, 5.0) in layout_lint._story_parts(s, 0)\n    s["auto_exterior"] = False\n    s["ext_walls"] = []                                       # no wall there: then it is one floor\n    assert len(layout_lint.open_floors(s)) == 1\n    assert tactical.exterior_parts((-5.0, -5.0, 5.0, 5.0), ("N", "W")) == [("X", 5.0, -5.0, 5.0),\n                                                                           ("Y", -5.0, -5.0, 5.0)]\n\n\ndef test_a_room_naming_open_to_loads():\n    s = _spec(front={"open_to": ["back"]})\n    spec = spec_loader.spec_from_dict(s)\n    assert spec.rooms[0].open_to == ["back"] and spec.rooms[1].open_to == []\n    assert "front" in tactical.build_graph(spec)["back"]       # still one floor to the engine\n\n\ndef test_a_deli_made_from_its_preset_comes_out_sorted():\n    d = presets.make("corner_deli")\n    assert layout_lint.open_floors(d) == []\n    rooms = {r["id"]: r for r in d["rooms"]}\n    assert "deli_counter" in rooms["customer_floor"].get("open_to", [])\n    assert any(o.get("tag") == "market_aisles_to_kitchen" for p in d["partitions"] for o in p.get("openings", []))\n    assert layout_lint.reachability_findings(d) == []\n'}
WALK_REACH_SENTENCE = " By the same call, rowhouse_raid's basement vault (0.234.0), the objective: its approach's wall stopped 2 m short of the north wall until the factory's roadmap 260 table closed it, and a reinforced door and a breach are its ways in."
CHANGELOG = '## [0.234.0] - the walker\'s open-floor table: each pair of rooms one floor or two; an exterior wall covers its line; a room may name `open_to`\n\n**The factory\'s roadmap 260, from 255.** 0.223.0 named every open floor nobody named (layout_lint L26) and froze the\nlibrary\'s 49 in `open_floor_baseline.json` for the walker to sort one pair at a time. On the review page the walker\nanswered "Wall it" for every pair, unsure whether a wall would shut a room nobody could open -- "we aren\'t making the\ndoors in level factory because we are going to have networked doors added later" -- and, told that a wall here\ncarries its own openings and that every door opening already ships to gameplay as a door socket (Dispatch\'s\n`interactives.json`), approved in chat a table by room pair: "go ahead with the 255 table, your defaults are good".\nThe 49 are 20 pairs of room ids repeated through shared recipes.\n\n### Added\n- `open_floor_rules.py`: `RULES`, one row per pair of room ids.\n  - OPEN, the floor is meant (`open_to`): customer_floor|deli_counter, front_hall|kitchen, the garage decks,\n    exec_lobby|exec_anteroom, north_aisles|north_dock -- and, the factory\'s call where a stair stands on the line,\n    lobby|ground_bullpen (the office\'s only stair at (0, 0)) and corner_deli_heist_01\'s stair well against its two\n    cold rooms (`main_stack` reserves y 6.05..12.65: a wall on the well\'s south edge runs inside the stair, L21, and\n    one on its north edge ends at the centre of `cold_n_access`, L18).\n  - WALL, the rest: each stretch of the meeting line no partition covers is closed -- an abutting partition extended\n    over it, each of its openings kept where the builder stands it, else a partition of its own in its neighbour\'s\n    material; an opening a new wall\'s end would split slides along its own wall by whole grid cells until clear\n    (L18\'s own prescription); then one door of the agent contract\'s width where nothing walkable joins the two rooms\n    any more (`DOORWAY_POLICY = "keep_pair_joined"`, a call meant to be changed; "only_if_sealed" the other), never\n    into an objective room.\n  - A WALL row that would leave a spec failing any lint rule it passed is taken back whole and named.\n- `migrate_open_floor_rules.py`: the one-shot, idempotent migration over specs/ (not the mission\'s `lf_*`).\n- `presets.make` applies the table to every spec it writes, and trims a piece the new wall runs through.\n- `test_open_floor_rules.py` (11). On 0.233.0 the file does not collect; with the table alone beside 0.233.0, three\n  fail -- the exterior wall, `open_to` loading and the deli preset.\n\n### Fixed\n- An exterior wall covers its line as a partition does (`tactical.exterior_parts` and `exterior_sides`; layout_lint\'s\n  `_story_parts` and `_exterior_sides`, read with `LevelSpec`\'s defaults). The gas stations\' forecourts are outdoor\n  rooms that meet the shop along y -11, where the front wall stands with its doors and windows; read with partitions\n  alone, L26 named seven such pairs and the tactical graph held four edges through a wall with no door in it. On the\n  library\'s 128 specs with rooms: L26 49 -> 42 by this alone, graph edges 1,362 -> 1,358, L12 and L24 unchanged.\n- `Room` takes `open_to`. The schema has admitted it since 0.223.0, but `spec_loader`\'s `Room(**r)` refused any spec\n  naming it: every spec the table opens would have failed to load into the builder.\n- `build_graph`\'s docstring said it returned "(adjacency, info)"; it returns the adjacency.\n\n### Library\n- Migrated, 23 specs: 20 pairs given `open_to`; 24 stretches closed by running a partition on to its wall -- the\n  rowhouse, the walk-up, the auto shops\' and the pawn shops\' upper floors -- and 7 partitions added: a kitchen wall\n  in each of the six delis (x 7, y -14..6, a door at y -4), each deli\'s stockroom gate slid 0.5 m west to clear its\n  end, and corner_deli_heist_01\'s cold rooms walled apart (x -16.8, a piece of its own, since running its neighbour\n  on would have slid `cold_w_access` 0.125 m on the grid; a door at y 3.625). Nine doors in all, `kitchen_to_garage_bay`\n  in the rowhouse and the walk-up among them; none into rowhouse_raid\'s vault, the objective.\n- 0 open floors nobody named in 159 built specs; L12 0; L24 one room more, rowhouse_raid\'s basement vault -- the\n  objective, behind a reinforced door and a breach -- kept by the walker\'s rule (`walk_reach_baseline.json`); no new\n  lint FAIL in any migrated spec; the tactical graph loses only the four forecourt edges.\n- Refurnished (`migrate_furnish_recipes.py`): three specs move, by the new doors -- deli_a02\'s kitchen work tables\n  and cartons, a pallet in front of corner_deli_heist_01\'s new cold-room door (dropped), apartment_walkup_a01\'s garage\n  cartons and chairs; 16 pieces out, 14 in. The untouched library refurnished changes nothing, the control.\n  CATALOG.md regenerated.\n\n### Changed\n- L26\'s message offers the table.\n- `open_floor_rules.py` is a geometry source (`build_freshness`), with the migrations presets call while they write a\n  spec.\n- Tests: test_open_floor\'s warning test takes its open floor back out of rowhouse_raid; test_wall_over_void pins\n  night_pawn\'s wall at its captured run as it pins the stair; test_stair_back\'s library counts 34/17/15 -> 33/16/14,\n  the cold-room wall standing where `main_stack`\'s storey -1 side guard stood (x -16.6, y 6.05..6.25), the leg\'s\n  back kept.\n\n'
TESTS = "test_open_floor_rules.py"


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _walk_reach(text):
    b = json.loads(text)
    b["walk_unreachable"]["rowhouse_raid"] = ["basement_vault"]
    b["walk_unreachable"] = dict(sorted(b["walk_unreachable"].items()))
    b["counts"] = {"rooms": sum(len(v) for v in b["walk_unreachable"].values()), "shells": len(b["walk_unreachable"])}
    anchor = " an objective you breach into."
    assert b["reason"].count(anchor) == 1, "walk_reach_baseline.json's reason is not the one this patch read"
    b["reason"] = b["reason"].replace(anchor, anchor + WALK_REACH_SENTENCE)
    return json.dumps(b, indent=2) + "\n"


def _read(name):
    raw = (DC / name).read_bytes()
    if _sha(raw) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing written"
                         % (name, _sha(raw), PINS[name]))
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: deli_counter/%s has CRLF endings; these edits are LF" % name)
    return raw.decode("utf-8")


def _new_file_plan(name):
    p = DC / name
    if p.exists() and p.read_text(encoding="utf-8") != NEW_FILES[name]:
        raise SystemExit("REFUSED: deli_counter/%s exists and is not this patch's; nothing written" % name)
    return p


def main(argv):
    if "--tests" in argv:
        p = _new_file_plan(TESTS)
        p.write_text(NEW_FILES[TESTS], encoding="utf-8", newline="\n")
        print("wrote deli_counter/%s" % TESTS)
        return 0
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor for %r is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text
    out["walk_reach_baseline.json"] = _walk_reach(_read("walk_reach_baseline.json"))
    plans = {n: _new_file_plan(n) for n in NEW_FILES if n != TESTS or not (DC / n).exists()}
    v = DC / "VERSION"
    if v.read_text(encoding="utf-8").strip() != "Deli Counter 0.233.0":
        raise SystemExit("REFUSED: VERSION reads %r, not Deli Counter 0.233.0; nothing written" % v.read_text())
    cl = DC / "CHANGELOG.md"
    ctext = cl.read_bytes().decode("utf-8")
    if not ctext.startswith("## [0.233.0]"):
        raise SystemExit("REFUSED: CHANGELOG.md does not open on 0.233.0; nothing written")
    for name, text in out.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    for name, p in plans.items():
        p.write_text(NEW_FILES[name], encoding="utf-8", newline="\n")
    v.write_text("Deli Counter 0.234.0", encoding="utf-8")
    cl.write_bytes((CHANGELOG + ctext).encode("utf-8"))
    print("Deli Counter 0.234.0 applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: "
          "migrate_open_floor_rules.py, migrate_furnish_recipes.py, open_floor_baseline.py, catalog.py, the suite, "
          "build.py --all, check.py" % (len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
